const WHATSAPP_NUMBER='5571987912915';const messages={general:'Olá!Recebi a apresentação de patrocínio da SEMIN UFBA 2026 e gostaria de conversar sobre as possibilidades de parceria.',diamante:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre a Cota Diamante.',corindon:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre a Cota Córindon.',topazio:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre a Cota Topázio.',quartzo:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre a Cota Quartzo.',activation:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre uma ativação técnica,exposição de equipamento ou outra modalidade de parceria.',documentaryMaster:'Olá!Recebi a apresentação da SEMIN UFBA 2026 e gostaria de conversar sobre o financiamento integral do documentário dos 50 anos e o patrocínio master da edição histórica.'};const plans=[{id:'diamante',name:'Diamante',price:'R$ 20.000',kicker:'Máxima presença,conteúdo e legado',badge:'Patrocínio Principal · Edição 50 Anos',buttonText:'Garantir Cota Diamante',description:'O investimento de R$ 20 mil é direcionado à produção do documentário comemorativo dos 50 anos,somando a esse legado uma presença completa na SEMIN UFBA 2026.',benefits:[ 'Exposição da logomarca em cartazes,folders,banners e mídias sociais do evento','Inserção de brindes e folheto publicitário na pasta dos participantes','Espaço para exposição da empresa na Escola Politécnica da UFBA','Palestra de 30 minutos+10 minutos de Q&A sobre tema inspirado no norte do congresso','Representante em um dos painéis do evento para apresentar a visão da empresa','Logomarca no porta-moedas da moeda comemorativa dos 50 anos da Engenharia de Minas','R$ 20 mil direcionados à produção do documentário dos 50 anos,com reconhecimento da marca como patrocinadora','Patrocinador Oficial do DESAFIO SEMIN UFBA' ],features:[1,1,1,1,1,1,1,1]},{id:'corindon',name:'Córindon',price:'R$ 10.000',kicker:'Presença,conteúdo e relacionamento',badge:'Alta Presença&Conteúdo',buttonText:'Garantir Cota Córindon',description:'Presença institucional,conteúdo técnico e relacionamento direto com o público do evento.',benefits:[ 'Exposição da logomarca em cartazes,folders,banners e mídias sociais','Inserção de brindes e folheto publicitário na pasta dos participantes','Espaço para exposição da empresa na Escola Politécnica da UFBA','Palestra de 30 minutos+10 minutos de Q&A sobre tema inspirado no norte do congresso','Representante em um dos painéis do evento','Patrocinador Oficial do DESAFIO SEMIN UFBA' ],features:[1,1,1,1,1,1,0,0]},{id:'topazio',name:'Topázio',price:'R$ 5.000',kicker:'Visibilidade e autoridade técnica',badge:'Compartilhamento Técnico',buttonText:'Garantir Cota Topázio',description:'Visibilidade institucional combinada à oportunidade de compartilhar conhecimento com o público.',benefits:[ 'Exposição da logomarca em cartazes,folders,banners e mídias sociais','Inserção de brindes e folheto publicitário na pasta dos participantes','Palestra de 30 minutos+10 minutos de Q&A sobre tema inspirado no norte do congresso' ],features:[1,1,0,1,0,0,0,0]},{id:'quartzo',name:'Quartzo',price:'R$ 2.500',kicker:'Apoio e presença institucional',badge:'Apoio Institucional',buttonText:'Garantir Cota Quartzo',description:'Uma porta de entrada para empresas que desejam apoiar e estar presentes na SEMIN UFBA 2026.',benefits:[ 'Exposição da logomarca em cartazes,folders,banners e mídias sociais','Inserção de brindes e folheto publicitário na pasta dos participantes' ],features:[1,1,0,0,0,0,0,0]}];const featureNames=[ 'Marca em materiais e mídias','Brindes e folhetos na pasta','Espaço para exposição na Poli-UFBA','Palestra técnica(30m+10m Q&A)','Representante em painel temático','Patrocinador do Desafio SEMIN','Marca na Moeda Comemorativa','Crédito no Documentário 50 Anos' ];const waUrl=key=>`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(messages[key]||messages.general)}`;document.querySelectorAll('.whatsapp').forEach(link=>{link.href=waUrl(link.dataset.message||'general');link.target='_blank';link.rel='noopener noreferrer';});const planContainer=document.querySelector('#plan-cards');if(planContainer){planContainer.innerHTML=plans.map(plan=>`<article class="plan-card ${plan.id==='diamante' ? 'featured':''}" data-plan="${plan.id}">${plan.badge ? `<span class="plan-badge">${plan.badge}</span>`:''}<div class="plan-heading"><h3>Cota ${plan.name}</h3><p class="plan-kicker">${plan.kicker}</p><div class="price">${plan.price}</div></div><p class="plan-description">${plan.description}</p><ul class="benefits">${plan.benefits.map(item=>`<li>${item}</li>`).join('')}</ul><a class="button" target="_blank" rel="noopener noreferrer" href="${waUrl(plan.id)}">${plan.buttonText||`Quero conversar sobre a ${plan.name}`}</a><small class="plan-reassurance">Alinhamento direto com a coordenação institucional</small></article>`).join('');}const compDesktop=document.querySelector('#comparison-desktop');if(compDesktop){compDesktop.innerHTML=`<table><thead><tr><th scope="col">Contrapartida Oficial</th>${plans.map(p=>`<th scope="col">${p.name}</th>`).join('')}</tr></thead><tbody>${featureNames.map((name,i)=>`<tr><th scope="row">${name}</th>${plans.map(p=>`<td class="${p.features[i] ? 'yes':'no'}"><span class="sr-only">${p.features[i] ? 'Sim':'Não'}</span>${p.features[i] ? '✓':'—'}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Investimento</th>${plans.map(p=>`<td><strong>${p.price}</strong></td>`).join('')}</tr></tbody></table>`;}const compMobile=document.querySelector('#comparison-mobile');if(compMobile){compMobile.innerHTML=plans.map((p,i)=>`<details ${i===0 ? 'open':''}><summary>${p.name}· ${p.price}</summary><dl>${featureNames.map((name,j)=>`<dt>${name}</dt><dd>${p.features[j] ? 'Sim':'Não'}</dd>`).join('')}</dl></details>`).join('');}const planCards=[...document.querySelectorAll('.plan-card')];document.querySelectorAll('[data-focus-plan]').forEach(button=>{button.addEventListener('click',()=>{const target=button.dataset.focusPlan;if(target==='activation'){document.querySelector('.tech')?.scrollIntoView({behavior:'smooth',block:'center'});return;}planCards.forEach(card=>card.classList.toggle('is-focus',card.dataset.plan===target));planCards.find(card=>card.dataset.plan===target)?.scrollIntoView({behavior:'smooth',block:'center'});window.setTimeout(()=>planCards.forEach(card=>card.classList.remove('is-focus')),1800);});});const toggle=document.querySelector('.menu-toggle');const menu=document.querySelector('#nav-menu');if(toggle&&menu){const setMenu=open=>{toggle.setAttribute('aria-expanded',String(open));const sr=toggle.querySelector('.sr-only');if(sr)sr.textContent=open ? 'Fechar menu':'Abrir menu';menu.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);};toggle.addEventListener('click',()=>setMenu(toggle.getAttribute('aria-expanded')!=='true'));menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setMenu(false)));document.addEventListener('keydown',event=>{if(event.key==='Escape')setMenu(false);});}